<?php
class PlanillaAjusteConsultaModel{private $db;function __construct(PDO $db){$this->db=$db;}function datos(int $id):array{$q=$this->db->prepare('SELECT * FROM periodos_pago WHERE id_periodo_pago=?');$q->execute([$id]);$periodo=$q->fetch();if(!$periodo)throw new InvalidArgumentException('Período no encontrado.');$q=$this->db->prepare("SELECT pd.id_planilla_detalle,pd.monto_pagar,CONCAT(p.apellidos,', ',p.nombres) trabajador FROM planilla_detalles pd JOIN vinculos_laborales v ON v.id_vinculo=pd.id_vinculo JOIN personas p ON p.id_persona=v.id_persona WHERE pd.id_periodo_pago=? ORDER BY p.apellidos,p.nombres");$q->execute([$id]);$detalles=$q->fetchAll();$q=$this->db->prepare("SELECT a.*,CONCAT(p.apellidos,', ',p.nombres) trabajador,COALESCE(NULLIF(CONCAT(COALESCE(pr.apellidos,''),', ',COALESCE(pr.nombres,'')),', '),u.usuario,'Usuario') responsable FROM planilla_ajustes a JOIN planilla_detalles pd ON pd.id_planilla_detalle=a.id_planilla_detalle JOIN vinculos_laborales v ON v.id_vinculo=pd.id_vinculo JOIN personas p ON p.id_persona=v.id_persona LEFT JOIN usuarios u ON u.id_usuario=a.registrado_por LEFT JOIN personas pr ON pr.id_persona=u.id_persona WHERE pd.id_periodo_pago=? ORDER BY a.registrado_en DESC");$q->execute([$id]);$ajustes=$q->fetchAll();return compact('periodo','detalles','ajustes');}}
